\usetikzlibrary{shapes.geometric, arrows.meta, positioning}

\begin{tikzpicture}[
  node distance=8mm,
  box/.style={draw, rounded corners, minimum width=24mm, minimum height=8mm},
  choice/.style={draw, diamond, aspect=2, inner sep=1pt},
  every edge/.style={draw, -{Stealth}},
]
  \node[box] (start) {Start};
  \node[box, below=of start] (step) {Do the work};
  \node[choice, below=of step] (check) {Done?};
  \node[box, below=of check] (stop) {Stop};

  \path (start) edge (step)
  (step) edge (check)
  (check) edge node[right] {yes} (stop);
  \draw[-{Stealth}] (check.east) -- ++(8mm,0) |- node[pos=0.25, right] {no} (step.east);
\end{tikzpicture}

\usetikzlibrary{shapes.geometric, shapes.misc, arrows.meta, positioning}

\begin{tikzpicture}[
  node distance=6mm and 12mm,
  every node/.style={font=\small},
  terminal/.style={rounded rectangle, draw, minimum width=20mm, minimum height=7mm},
  process/.style={rectangle, draw, minimum width=26mm, minimum height=7mm},
  io/.style={trapezium, trapezium stretches body, trapezium left angle=70, trapezium right angle=110, draw, minimum width=22mm, minimum height=7mm},
  decision/.style={diamond, aspect=2, draw, inner sep=1pt},
  arrow/.style={-{Stealth}, thick},
]
  \node[terminal] (start) {Start};
  \node[io, below=of start] (read) {Read $n$};
  \node[process, below=of read] (init) {$i \gets 1$, $s \gets 0$};
  \node[decision, below=of init] (test) {$i \le n$?};
  \node[process, right=of test] (add) {$s \gets s + i$, $i \gets i + 1$};
  \node[io, below=of test] (print) {Print $s$};
  \node[terminal, below=of print] (stop) {Stop};

  \draw[arrow] (start) -- (read);
  \draw[arrow] (read) -- (init);
  \draw[arrow] (init) -- (test);
  \draw[arrow] (test) -- node[above] {yes} (add);
  \draw[arrow] (add) |- (init);
  \draw[arrow] (test) -- node[right] {no} (print);
  \draw[arrow] (print) -- (stop);
\end{tikzpicture}

\usetikzlibrary{shapes.geometric, arrows.meta, positioning}

\begin{tikzpicture}[
  node distance=8mm and 12mm,
  every node/.style={font=\small, align=center},
  decision/.style={diamond, aspect=2.2, draw, inner sep=1pt},
  action/.style={rectangle, rounded corners, draw, minimum height=8mm, text width=26mm},
  arrow/.style={-{Stealth}, thick},
]
  \node[action] (start) {The lamp does\\not turn on};
  \node[decision, below=of start] (plug) {Plugged in?};
  \node[action, right=of plug] (fix1) {Plug it in};
  \node[decision, below=of plug] (bulb) {Bulb burned\\out?};
  \node[action, right=of bulb] (fix2) {Replace the bulb};
  \node[action, below=of bulb] (fix3) {Have the lamp\\repaired};

  \draw[arrow] (start) -- (plug);
  \draw[arrow] (plug) -- node[above] {no} (fix1);
  \draw[arrow] (plug) -- node[left] {yes} (bulb);
  \draw[arrow] (bulb) -- node[above] {yes} (fix2);
  \draw[arrow] (bulb) -- node[left] {no} (fix3);
\end{tikzpicture}

\usetikzlibrary{shapes.geometric, arrows.meta, positioning}

\begin{tikzpicture}[
  node distance=6mm and 7mm,
  every node/.style={font=\small},
  stage/.style={rectangle, rounded corners, draw, minimum height=9mm, minimum width=16mm},
  gate/.style={diamond, aspect=1.6, draw, inner sep=1pt},
  arrow/.style={-{Stealth}, thick},
]
  \node[stage] (commit) {Commit};
  \node[stage, right=of commit] (build) {Build};
  \node[gate, right=of build] (test) {Tests pass?};
  \node[stage, right=of test] (deploy) {Deploy};
  \node[stage, below=10mm of test] (notify) {Notify the author};

  \draw[arrow] (commit) -- (build);
  \draw[arrow] (build) -- (test);
  \draw[arrow] (test) -- node[above] {yes} (deploy);
  \draw[arrow] (test) -- node[right] {no} (notify);
  \draw[arrow] (notify) -| (commit);
\end{tikzpicture}

\usetikzlibrary{arrows.meta}

\begin{tikzpicture}[
  x=0.94cm,
  every node/.style={font=\small},
  task/.style={rectangle, rounded corners, draw, minimum width=19mm, minimum height=8mm},
  arrow/.style={-{Stealth}, thick},
]
  \foreach \y/\lane in {0/Customer, -1.6/Shop, -3.2/Warehouse} {
    \draw[gray!60] (0,\y+0.8) rectangle (12.2,\y-0.8);
    \node[rotate=90, font=\small\bfseries] at (0.35,\y) {\lane};
  }
  \draw[gray!60] (0.7,0.8) -- (0.7,-4);

  \node[task] (order) at (2.1,0) {Place order};
  \node[task] (check) at (4.4,-1.6) {Check stock};
  \node[task] (pack) at (6.7,-3.2) {Pack items};
  \node[task] (ship) at (9,-1.6) {Ship order};
  \node[task] (receive) at (11.1,0) {Receive};

  \draw[arrow] (order) |- (check);
  \draw[arrow] (check) |- (pack);
  \draw[arrow] (pack) -| (ship);
  \draw[arrow] (ship) |- (receive);
\end{tikzpicture}

\usetikzlibrary{arrows.meta, positioning}

\begin{tikzpicture}[
  node distance=8mm and 10mm,
  block/.style={draw, thick, minimum height=10mm, minimum width=16mm},
  sum/.style={draw, thick, circle, inner sep=0pt, minimum size=6mm},
  arrow/.style={-{Stealth}, thick},
]
  \coordinate (in);
  \node[sum, right=of in] (sum) {};
  \node[block, right=of sum] (ctrl) {$C(s)$};
  \node[block, right=of ctrl] (plant) {$G(s)$};
  \coordinate[right=6mm of plant] (tap);
  \coordinate[right=10mm of tap] (out);
  \node[block, below=of plant] (sensor) {$H(s)$};

  \draw[arrow] (in) -- node[above] {$r$} (sum);
  \draw[arrow] (sum) -- node[above] {$e$} (ctrl);
  \draw[arrow] (ctrl) -- node[above] {$u$} (plant);
  \draw[thick] (plant) -- (tap);
  \draw[arrow] (tap) -- node[above] {$y$} (out);
  \draw[arrow] (tap) |- (sensor);
  \draw[arrow] (sensor) -| node[pos=0.9, right] {$-$} (sum);
  \fill (tap) circle (1.5pt);
  \node at ([shift={(-4mm,4mm)}]sum) {$+$};
\end{tikzpicture}

\usetikzlibrary{arrows.meta, positioning}

\begin{tikzpicture}[
  node distance=5mm and 12mm,
  block/.style={draw, thick, minimum height=11mm, minimum width=24mm},
  sum/.style={draw, thick, circle, inner sep=1pt, minimum size=7mm},
  arrow/.style={-{Stealth}, thick},
]
  \node[block] (i) {$K_i \int_0^t e(\tau)\,d\tau$};
  \node[block, above=of i] (p) {$K_p\, e(t)$};
  \node[block, below=of i] (d) {$K_d\, \dfrac{de}{dt}$};
  \coordinate[left=of i] (split);
  \coordinate[left=10mm of split] (in);
  \node[sum, right=of i] (sum) {$\Sigma$};
  \coordinate[right=10mm of sum] (out);

  \draw[thick] (in) node[left] {$e(t)$} -- (split);
  \fill (split) circle (1.5pt);
  \foreach \b in {p, i, d}
  \draw[arrow] (split) |- (\b);
  \draw[arrow] (p) -| (sum);
  \draw[arrow] (i) -- (sum);
  \draw[arrow] (d) -| (sum);
  \draw[arrow] (sum) -- (out) node[right] {$u(t)$};
\end{tikzpicture}

\usetikzlibrary{arrows.meta}

\begin{tikzpicture}[
  block/.style={draw, thick, minimum size=9mm},
  sum/.style={draw, thick, circle, inner sep=0pt, minimum size=5mm},
  arrow/.style={-{Stealth}, thick},
]
  \node[block] (B) at (1.6,0) {$B$};
  \node[sum] (s1) at (3,0) {};
  \node[block] (int) at (4.4,0) {$\int$};
  \node[block] (C) at (6.6,0) {$C$};
  \node[sum] (s2) at (8,0) {};
  \node[block] (A) at (4.4,-1.6) {$A$};
  \node[block] (D) at (4.4,1.6) {$D$};

  \draw[thick] (0,0) node[left] {$u$} -- (0.6,0);
  \draw[arrow] (0.6,0) -- (B);
  \draw[arrow] (B) -- (s1);
  \draw[arrow] (s1) -- node[above] {$\dot{x}$} (int);
  \draw[arrow] (int) -- node[above] {$x$} (C);
  \draw[arrow] (C) -- (s2);
  \draw[arrow] (s2) -- (9.2,0) node[right] {$y$};
  \draw[arrow] (5.6,0) |- (A);
  \draw[arrow] (A) -| (s1);
  \draw[arrow] (0.6,0) |- (D);
  \draw[arrow] (D) -| (s2);
  \fill (0.6,0) circle (1.5pt) (5.6,0) circle (1.5pt);
\end{tikzpicture}

\usetikzlibrary{arrows.meta, positioning, fit}

\begin{tikzpicture}[
  node distance=6mm and 8mm,
  every node/.style={font=\small},
  block/.style={draw, thick, minimum height=9mm, minimum width=20mm},
  group/.style={draw, dashed, gray, inner sep=3mm},
  arrow/.style={-{Stealth}, thick},
]
  \node[block] (src) {Source};
  \node[block, right=of src] (enc) {Encoder};
  \node[block, right=of enc] (mod) {Modulator};
  \node[block, below=14mm of mod] (ch) {Channel};
  \node[block, below=14mm of ch] (dem) {Demodulator};
  \node[block, left=of dem] (dec) {Decoder};
  \node[block, left=of dec] (sink) {Destination};
  \node[right=10mm of ch] (noise) {Noise};

  \node[group, fit=(src)(mod), label=above:Transmitter] {};
  \node[group, fit=(sink)(dem), label=below:Receiver] {};

  \draw[arrow] (src) -- (enc);
  \draw[arrow] (enc) -- (mod);
  \draw[arrow] (mod) -- (ch);
  \draw[arrow] (ch) -- (dem);
  \draw[arrow] (dem) -- (dec);
  \draw[arrow] (dec) -- (sink);
  \draw[arrow, dashed] (noise) -- (ch);
\end{tikzpicture}

\begin{tikzpicture}[
  level distance=12mm,
  level 1/.style={sibling distance=30mm},
  level 2/.style={sibling distance=15mm},
]
  \node {Root}
  child { node {A}
    child { node {A1} }
    child { node {A2} }
  }
  child { node {B}
    child { node {B1} }
    child { node {B2} }
  };
\end{tikzpicture}

\begin{tikzpicture}[
  grow=right, sloped,
  level 1/.style={level distance=30mm, sibling distance=28mm},
  level 2/.style={level distance=30mm, sibling distance=13mm},
  every node/.style={font=\small},
  edge from parent/.style={draw, thick},
  event/.style={draw, rounded corners, inner sep=3pt},
  outcome/.style={anchor=west},
]
  \node[circle, fill, inner sep=1.5pt] {}
  child { node[event] {Dry}
    child { node[outcome] {On time \quad $0.7 \times 0.9 = 0.63$} edge from parent node[below] {$0.9$} }
    child { node[outcome] {Late \quad $0.7 \times 0.1 = 0.07$} edge from parent node[above] {$0.1$} }
    edge from parent node[below] {$0.7$}
  }
  child { node[event] {Rain}
    child { node[outcome] {On time \quad $0.3 \times 0.4 = 0.12$} edge from parent node[below] {$0.4$} }
    child { node[outcome] {Late \quad $0.3 \times 0.6 = 0.18$} edge from parent node[above] {$0.6$} }
    edge from parent node[above] {$0.3$}
  };
\end{tikzpicture}

\begin{tikzpicture}[
  level distance=12mm,
  level 1/.style={sibling distance=36mm},
  level 2/.style={sibling distance=18mm},
  level 3/.style={sibling distance=10mm},
  every node/.style={circle, draw, thick, minimum size=7mm, inner sep=0pt, font=\small},
  found/.style={fill=orange!25, draw=orange!85!black},
]
  \node[found] (root) {8}
  child { node[found] (a) {3}
    child { node {1} }
    child { node[found] (b) {6}
      child { node {4} }
      child { node {7} }
    }
  }
  child { node {10}
    child[missing]
    child { node {14}
      child { node {13} }
      child[missing]
    }
  };
  \draw[orange!85!black, very thick] (root) -- (a) -- (b);
\end{tikzpicture}

\begin{tikzpicture}[
  level distance=11mm,
  level 1/.style={sibling distance=30mm},
  level 2/.style={sibling distance=15mm},
  key/.style={circle, draw, thick, minimum size=7mm, inner sep=0pt, font=\small},
  cell/.style={draw, thick, minimum size=7mm, font=\small},
]
  \node[key] {1}
  child { node[key] {3}
    child { node[key] {7} }
    child { node[key] {4} }
  }
  child { node[key] {2}
    child { node[key] {9} }
    child { node[key] {5} }
  };
  \foreach \k [count=\i from 0] in {1, 3, 2, 7, 4, 9, 5} {
    \node[cell] at (\i*0.7 - 2.1, -3.4) {\k};
    \node[font=\scriptsize, gray] at (\i*0.7 - 2.1, -4) {\i};
  }
\end{tikzpicture}

