\end{forest}

\begin{tikzpicture}
  \draw[thick, ->] (0,0) -- (10,0);
  \foreach \x/\year/\event in {1/2021/Founded, 3/2022/First hire, 5/2023/Launch, 7/2024/Funding, 9/2025/Expansion} {
    \draw (\x,0.15) -- (\x,-0.15) node[below] {\year};
